    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    authorUserId: integer("author_user_id").notNull().references(() => usersTable.id),
    // Role AT THE TIME OF WRITING — kept even if the author's role changes.
    authorRole: text("author_role").notNull(),
    body: text("body").notNull(),
    createdAt: timestamp("created_at").notNull().defaultNow()
