// ../../lib/db/src/schema/scorecards.ts
var inspectionScorecardsTable = pgTable(
  "inspection_scorecards",
  {
    id: serial("id").primaryKey(),
    companyId: integer("company_id").notNull().references(() => companiesTable.id),
    inspectionId: integer("inspection_id").notNull().references(() => inspectionsTable.id, { onDelete: "cascade" }),
    // Denormalized for per-technician aggregation without joins.
    technicianName: text("technician_name").notNull().default(""),
    qualityScore: integer("quality_score").notNull(),
    components: jsonb("components").$type().notNull(),
    missedOpportunities: jsonb("missed_opportunities").$type().notNull().default([]),
    // Severity-weighted risk snapshot FROZEN at computation time so history
    // doesn't shift as later inspections happen.
    riskScore: integer("risk_score").notNull(),
    riskLevel: text("risk_level").$type().notNull(),
    findingsCount: integer("findings_count").notNull().default(0),
    photosAnalyzed: integer("photos_analyzed").notNull().default(0),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
    // Delivery idempotency: set to true the first time a critical-risk push is
    // successfully claimed for this inspection. The atomic claim (UPDATE WHERE
    // critical_alert_sent = false) ensures exactly-once delivery across retries
    // and concurrent finalization paths. NOT reset by re-analysis upserts so
    // the owner isn't spammed on re-runs.
    criticalAlertSent: boolean("critical_alert_sent").notNull().default(false)
  },
  (t2) => ({
    companyIdx: index("inspection_scorecards_company_idx").on(t2.companyId),
    // One scorecard per inspection — recomputation upserts.
    inspectionIdx: uniqueIndex("inspection_scorecards_inspection_idx").on(t2.inspectionId)
  })
);

