var MAX_MESSAGE = 500;
var ALLOWED_CONTEXT_KEYS = /* @__PURE__ */ new Set([
  "status",
  "statusCode",
  "code",
  "step",
  "stage",
  "mediaType",
  "filename",
  "count",
  "kind",
  "operation",
  "model",
  "durationMs",
  "route",
  "field",
  "reason"
]);
function sanitizeContext(context) {
  if (!context || typeof context !== "object") return null;
  const out = {};
  for (const [k, v] of Object.entries(context)) {
    if (!ALLOWED_CONTEXT_KEYS.has(k)) continue;
    if (v == null) continue;
    if (typeof v === "string") out[k] = v.slice(0, 200);
    else if (typeof v === "number" || typeof v === "boolean") out[k] = v;
  }
  return Object.keys(out).length > 0 ? out : null;
}
async function logErrorEvent(category, input) {
  try {
    if (input.companyId == null) return;
    await db.insert(errorEventsTable).values({
      companyId: input.companyId,
      userId: input.userId ?? null,
      category,
      message: String(input.message ?? "").slice(0, MAX_MESSAGE),
      context: sanitizeContext(input.context),
      inspectionId: input.inspectionId ?? null,
      reportId: input.reportId ?? null,
      source: input.source ?? "server"
    });
  } catch {
  }
}

