    const base = prices[0];
    if (!base) {
      throw new Error(
        `No ${tier} ${period} base price found in stripe.prices. Run the seed script and restart the server to trigger a backfill.`
      );
    }
    return {
      basePriceId: base.price_id,
      perSeatPriceId: void 0
    };
