    const { basePriceId, perSeatPriceId } = await this.resolvePriceIds(
      opts.tier,
      opts.period
    );
    const lineItems = [
      { price: basePriceId, quantity: 1 }
    ];
    const additionalSeats = opts.additionalSeats ?? 0;
