// src/lib/clerk-redirect-urls.ts
var NATIVE_REDIRECT_URLS = [
  "readyloq-app://sso-callback",
  // standard two-slash form (Linking.createURL without leading slash)
  "readyloq-app:///sso-callback"
  // three-slash form (empty host) — some Expo/platform combos produce this
];
var CLERK_API_BASE = "https://api.clerk.com/v1";
async function ensureClerkNativeRedirectUrls() {
  const secretKey = process.env.CLERK_SECRET_KEY;
  if (!secretKey) {
    logger3.warn("clerk redirect allowlist: CLERK_SECRET_KEY not set, skipping");
    return;
  }
  const headers = {
    Authorization: `Bearer ${secretKey}`,
    "Content-Type": "application/json"
  };
  try {
    const listRes = await fetch(`${CLERK_API_BASE}/redirect_urls?limit=100`, {
      headers
    });
    if (!listRes.ok) {
      logger3.warn(
        { status: listRes.status },
        "clerk redirect allowlist: failed to list redirect URLs"
      );
      return;
    }
    const body = await listRes.json();
    const existing = Array.isArray(body) ? body : body.data ?? [];
    const existingUrls = new Set(existing.map((r2) => r2.url));
    for (const url3 of NATIVE_REDIRECT_URLS) {
      if (existingUrls.has(url3)) {
        logger3.info({ url: url3 }, "clerk redirect allowlist: already registered");
        continue;
      }
      const createRes = await fetch(`${CLERK_API_BASE}/redirect_urls`, {
        method: "POST",
        headers,
        body: JSON.stringify({ url: url3 })
      });
      if (createRes.ok) {
        logger3.info({ url: url3 }, "clerk redirect allowlist: registered");
      } else {
        const errText = await createRes.text().catch(() => "");
        logger3.warn(
          { url: url3, status: createRes.status, error: errText.slice(0, 500) },
          "clerk redirect allowlist: failed to register"
        );
      }
    }
  } catch (err) {
    logger3.warn({ err }, "clerk redirect allowlist: unexpected error");
  }
}

