// src/lib/backfill-opportunity-values.ts
var OPEN_STATUSES3 = ["new", "reviewed", "quoted"];
async function backfillOpportunityValues() {
  const rows = await db.select({
    id: opportunitiesTable.id,
    propertyAddress: opportunitiesTable.propertyAddress,
    estimatedValueTier: opportunitiesTable.estimatedValueTier,
    riskLevel: opportunitiesTable.riskLevel,
    status: opportunitiesTable.status,
    // Profile may not exist; fall back to "residential" below.
    propertyType: propertyProfilesTable.propertyType
  }).from(opportunitiesTable).leftJoin(
    propertyProfilesTable,
    and(
      eq(propertyProfilesTable.companyId, opportunitiesTable.companyId),
      eq(propertyProfilesTable.siteAddress, opportunitiesTable.propertyAddress)
    )
  ).where(
    and(
      inArray(opportunitiesTable.status, OPEN_STATUSES3),
      isNull(opportunitiesTable.estimatedAnnualValue)
    )
  );
  if (rows.length === 0) {
    logger3.info("backfillOpportunityValues: nothing to backfill");
    return;
  }
  logger3.info({ count: rows.length }, "backfillOpportunityValues: starting");
  let updated = 0;
  let skipped = 0;
  for (const row of rows) {
    const propertyType = row.propertyType ?? "residential";
    const tier = row.estimatedValueTier ?? "medium";
    const riskLevel = row.riskLevel ?? null;
    const value = calculateEstimatedAnnualValue({
      propertyType,
      tier,
      riskLevel,
      squareFootage: null
      // not stored on the profile; pricing engine uses category default
    });
    const result = await db.update(opportunitiesTable).set({ estimatedAnnualValue: value, updatedAt: /* @__PURE__ */ new Date() }).where(
      and(
        eq(opportunitiesTable.id, row.id),
        isNull(opportunitiesTable.estimatedAnnualValue)
      )
    ).returning({ id: opportunitiesTable.id });
    if (result.length > 0) {
      updated++;
    } else {
      skipped++;
    }
  }
  logger3.info(
    { updated, skipped, total: rows.length },
    "backfillOpportunityValues: complete"
  );
}

// src/lib/backfill-property-memory.ts
async function backfillPropertyMemory() {
  const inspections = await db.select().from(inspectionsTable).where(eq(inspectionsTable.status, "completed"));
  const addressed = inspections.filter(
    (i2) => !!normalizeAddressKey(i2.siteAddress ?? "")
  );
  if (addressed.length === 0) {
    logger3.info("backfillPropertyMemory: no completed inspections \u2014 skipping");
    return;
  }
  const existingMemory = await db.select().from(propertyMemoryTable);
  const coveredKeys = new Set(
    existingMemory.map((m2) => `${m2.companyId}::${m2.addressKey}`)
  );
  const pairsToWrite = /* @__PURE__ */ new Map();
  for (const insp of addressed) {
    const key = normalizeAddressKey(insp.siteAddress ?? "");
    const groupKey = `${insp.companyId}::${key}`;
    if (coveredKeys.has(groupKey)) continue;
    const existing = pairsToWrite.get(groupKey);
    const ts = insp.completedAt ? new Date(insp.completedAt).getTime() : 0;
    const existingTs = existing?.inspectionId ? 0 : -1;
    if (!existing || ts > existingTs) {
      pairsToWrite.set(groupKey, {
        companyId: insp.companyId,
        inspectionId: insp.id,
        siteAddress: insp.siteAddress ?? ""
      });
    }
  }
  if (pairsToWrite.size === 0) {
    logger3.info(
      "backfillPropertyMemory: all addresses already have memory rows"
    );
    return;
  }
  logger3.info(
    { pairs: pairsToWrite.size },
    "backfillPropertyMemory: starting"
  );
  let written = 0;
  let skipped = 0;
  for (const pair of pairsToWrite.values()) {
    try {
      await writePropertyMemory(pair);
      written++;
    } catch (err) {
      logger3.warn(
        { err, ...pair },
        "backfillPropertyMemory: failed to write memory row \u2014 skipping"
      );
      skipped++;
    }
  }
  logger3.info({ written, skipped }, "backfillPropertyMemory: complete");
}

